-- Bootstrap migration.
--
-- Better Auth owns `user`, `session`, `account`, and `verification`; those tables are
-- generated by the Better Auth CLI in the next migration rather than hand-written here.
-- This migration exists so the database has a schema_migrations row from the start and
-- so `SELECT 1` health checks have something to connect to.

CREATE TABLE IF NOT EXISTS _unbent_meta (
  key   TEXT PRIMARY KEY,
  value TEXT NOT NULL
);

INSERT OR REPLACE INTO _unbent_meta (key, value) VALUES ('schema_version', '1');
